//! The Unicode property tables behind `java.lang.Character`.
//!
//! `data/unicode.bin` is generated by `tools/unicode.py` from what the Java 8
//! oracle answers for every code point; nothing is downloaded. Format
//! (version 1, integers are LEB128 varints unless noted, "zz" is zigzag):
//!
//! ```text
//! "LZUC"  u16-le version (1)
//! run table  general category  (Character.getType)
//! run table  directionality + 1 (0 = undefined)
//! run table  flags: 1 mirrored, 2 ideographic, 4 alphabetic beyond letters
//!            and Nl, 8 lowercase beyond Ll, 16 uppercase beyond Lu, 32 Java
//!            identifier excluded although the category allows it
//! sigma      final-sigma automata, see below
//! sparse map upper, lower, title  (value = code point + zz-decoded offset)
//! sparse map digit value in radix 36, numeric value  (absolute, default -1)
//! multi map  special upper case mappings, special lower case mappings
//! u32-le  FNV-1a 32 checksum of every byte before it
//! ```
//!
//! A run table is `count` then `count` pairs `(length, value)` that must sum
//! to 0x110000. A sparse map is `count` then entries `(gap, n-1, [stride-1],
//! zz first, [zz step])`: the bracketed fields exist only when `n > 1`, `gap`
//! is the distance from the end of the previous entry, and element `i` of an
//! entry is code point `start + i*stride` with value `first + i*step`.
//! The sigma section is `nb na before_accept after_final after_terminal
//! nclasses`, then per class `nb + na` raw bytes (where each of the `nb`
//! states of the automaton that reads the text before a sigma, then each of
//! the `na` states of the one that reads the text after it, moves on that
//! character), then a run table giving the class of every code point. The
//! three masks are bit sets of states: the before-states in which a sigma is
//! preceded by a cased letter, the after-states in which it is not blocked by
//! a following one, and the after-states that nothing leaves.
//! A multi map is `count` then entries `(distance from the previous code
//! point, n, n code points)` with `2 <= n <= 3`, in ascending order.
//! Code points outside the tables (including negative ones) have category 0,
//! directionality -1, no flags, identity case maps and -1 digit values.

use std::sync::OnceLock;

use vm::{VmError, VmResult};

use crate::unicode_decode::parse;

static DATA: &[u8] = include_bytes!("../data/unicode.bin");

/// One run table: sorted run starts and the value of each run.
pub(crate) struct Runs {
    pub starts: Vec<u32>,
    pub values: Vec<u8>,
}

impl Runs {
    fn get(&self, cp: i32) -> u8 {
        let Some(cp) = u32::try_from(cp).ok().filter(|&c| c < 0x11_0000) else {
            return 0;
        };
        match self.starts.partition_point(|&s| s <= cp) {
            0 => 0,
            n => self.values[n - 1],
        }
    }
}

/// An arithmetic run of a sparse map.
pub(crate) struct Entry {
    pub start: u32,
    pub count: u32,
    pub stride: u32,
    pub first: i32,
    pub step: i32,
}

pub(crate) struct Sparse {
    pub entries: Vec<Entry>,
    pub relative: bool,
}

impl Sparse {
    /// The stored value for `cp`, if it has one.
    fn get(&self, cp: i32) -> Option<i32> {
        let u = u32::try_from(cp).ok()?;
        let at = self
            .entries
            .partition_point(|e| e.start <= u)
            .checked_sub(1)?;
        let e = &self.entries[at];
        let offset = u - e.start;
        if !offset.is_multiple_of(e.stride) || offset / e.stride >= e.count {
            return None;
        }
        // Validated at load: the first and last values fit, so every one does.
        let v = i64::from(e.first) + i64::from(offset / e.stride) * i64::from(e.step);
        i32::try_from(v + if self.relative { i64::from(cp) } else { 0 }).ok()
    }
}

/// A code point whose whole-string case mapping has several code points.
pub(crate) struct Multi {
    pub cp: u32,
    pub len: usize,
    pub chars: [u32; 3],
}

/// The final-sigma automata (module documentation).
pub(crate) struct Sigma {
    pub nb: usize,
    pub na: usize,
    pub masks: [u32; 3],
    pub columns: Vec<u8>,
    pub class: Runs,
}

pub struct Tables {
    pub(crate) category: Runs,
    pub(crate) direction: Runs,
    pub(crate) flags: Runs,
    pub(crate) sigma: Sigma,
    pub(crate) upper: Sparse,
    pub(crate) lower: Sparse,
    pub(crate) title: Sparse,
    pub(crate) digit: Sparse,
    pub(crate) numeric: Sparse,
    pub(crate) special_upper: Vec<Multi>,
    pub(crate) special_lower: Vec<Multi>,
}

impl Tables {
    /// `Character.getType`.
    pub fn category(&self, cp: i32) -> u8 {
        self.category.get(cp)
    }

    /// `Character.getDirectionality`, -1 when undefined.
    pub fn direction(&self, cp: i32) -> i32 {
        i32::from(self.direction.get(cp)) - 1
    }

    /// The flag bits listed in the module documentation.
    pub fn flags(&self, cp: i32) -> u8 {
        self.flags.get(cp)
    }

    pub fn upper(&self, cp: i32) -> i32 {
        self.upper.get(cp).unwrap_or(cp)
    }

    pub fn lower(&self, cp: i32) -> i32 {
        self.lower.get(cp).unwrap_or(cp)
    }

    pub fn title(&self, cp: i32) -> i32 {
        self.title.get(cp).unwrap_or(cp)
    }

    /// The value of `cp` as a digit in radix 36, or -1.
    pub fn digit36(&self, cp: i32) -> i32 {
        self.digit.get(cp).unwrap_or(-1)
    }

    /// The state the final-sigma automaton moves to on reading `cp`: before the sigma when
    /// `after` is false, after it otherwise.
    pub fn sigma_step(&self, state: i32, cp: i32, after: bool) -> i32 {
        let g = &self.sigma;
        let (width, base) = if after { (g.na, g.nb) } else { (g.nb, 0) };
        let class = usize::from(g.class.get(cp));
        let state = usize::try_from(state).ok().filter(|&s| s < width);
        // Validated at load: every class has nb + na bytes, each below its automaton's width.
        let at = state.map(|s| class * (g.nb + g.na) + base + s);
        at.and_then(|i| g.columns.get(i))
            .map_or(0, |&s| i32::from(s))
    }

    /// Which states count: 0 before-states preceded by a cased letter, 1 after-states that do
    /// not block a final sigma, 2 after-states nothing leaves.
    pub fn sigma_mask(&self, which: i32) -> i32 {
        usize::try_from(which)
            .ok()
            .and_then(|i| self.sigma.masks.get(i))
            .map_or(0, |&m| m as i32)
    }

    /// The multi-code-point mapping of `cp` in `String.toUpperCase` or `toLowerCase`.
    pub fn special(&self, cp: i32, upper: bool) -> Option<&[u32]> {
        let cp = u32::try_from(cp).ok()?;
        let list = if upper {
            &self.special_upper
        } else {
            &self.special_lower
        };
        let at = list.binary_search_by_key(&cp, |m| m.cp).ok()?;
        Some(&list[at].chars[..list[at].len])
    }

    /// `Character.getNumericValue`.
    pub fn numeric(&self, cp: i32) -> i32 {
        self.numeric.get(cp).unwrap_or(-1)
    }
}

/// The tables, decoded once. A corrupt build artifact is an internal error.
pub fn tables() -> VmResult<&'static Tables> {
    static TABLES: OnceLock<Result<Tables, String>> = OnceLock::new();
    match TABLES.get_or_init(|| parse(DATA)) {
        Ok(t) => Ok(t),
        Err(e) => Err(VmError::Internal(format!(
            "unicode tables are corrupt: {e}"
        ))),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::unicode_decode::fnv32;

    #[test]
    fn embedded_tables_answer_known_values() {
        let t = tables().expect("embedded tables parse");
        assert_eq!(t.category('A' as i32), 1);
        assert_eq!(t.category(0x10FFFF), 0);
        assert_eq!(t.upper('a' as i32), 'A' as i32);
        assert_eq!(t.lower(0x130), 'i' as i32);
        assert_eq!(t.digit36('z' as i32), 35);
        assert_eq!(t.digit36(0x0663), 3);
        assert_eq!(t.direction(-1), -1);
        assert_eq!(t.category(i32::MIN), 0);
        assert_eq!(t.upper(i32::MAX), i32::MAX);
        assert_eq!(t.numeric(0x2167), 8);
        assert_eq!(t.special(0xDF, true), Some(&[0x53, 0x53][..]));
        assert_eq!(t.special(0xDF, false), None);
        assert_eq!(t.special(-5, true), None);
        // A cased letter before a sigma accepts; a space after it ends the context.
        let after_a = t.sigma_step(0, 'A' as i32, false);
        assert_ne!(t.sigma_mask(0) >> after_a & 1, 0);
        assert_eq!(t.sigma_mask(0) >> t.sigma_step(0, ' ' as i32, false) & 1, 0);
        assert_eq!(t.sigma_step(99, 'A' as i32, true), 0);
        assert_eq!(t.sigma_mask(7), 0);
        assert_eq!(t.category(0x11_0000), 0);
    }

    #[test]
    fn corrupt_data_is_an_error_never_a_panic() {
        assert!(parse(&[]).is_err());
        assert!(parse(b"LZUC").is_err());
        for cut in (0..DATA.len()).step_by(7) {
            assert!(parse(&DATA[..cut]).is_err());
        }
        for i in (0..DATA.len()).step_by(11) {
            let mut bad = DATA.to_vec();
            bad[i] ^= 0x55;
            assert!(parse(&bad).is_err(), "flip at {i} went unnoticed");
        }
    }

    #[test]
    fn well_checksummed_garbage_is_rejected_cleanly() {
        for seed in 0..2000u32 {
            let mut body = DATA[..DATA.len() - 4].to_vec();
            let mut x = seed.wrapping_mul(2_654_435_761) | 1;
            for _ in 0..4 {
                x ^= x << 13;
                x ^= x >> 17;
                x ^= x << 5;
                let at = 6 + x as usize % (body.len() - 6);
                body[at] = (x >> 24) as u8;
            }
            let sum = fnv32(&body);
            body.extend_from_slice(&sum.to_le_bytes());
            let _ = parse(&body);
        }
    }
}
